  SELECT count(*) INTO n FROM public.biblioteca_vectores WHERE ingest_batch = 'OLA9_CTRIB_2024_01' AND es_norma_vigente = false AND metadata->>'rol' = 'CONTEXT';
  IF n <> 0 THEN RAISE EXCEPTION 'postcondición CONTEXT derogados = % (esperado 0)', n; END IF;
